algorithm SumOfEvens
    define count as integer;
    define i as integer;
    define number as integer;
    define total as integer;
    read count;
    total <- 0;
    for i <- 1 to count step 1 do
        read number;
        if number mod 2 = 0 then
            total <- total + number;
        endIf
    endFor
    write total;
endAlgorithm
